-- REVIEW CANDIDATE ONLY. Never execute in production or an application owner session.
-- Exact 7d2 genuine-service preimage, owned initdb OID10, fixed database/data path.
-- Render only through an owned driver that binds the held actual application connection and validates runtime values before execution.
-- The driver must error-stop, ROLLBACK on failure, verify the original preimage from a
-- new observer, impose a total deadline, and verify complete disposable cleanup.
-- Follow successful COMMIT with separate read-only v3 and membership-v1 observers,
-- fresh ordinary sessions and all27 default creator/schema/type object cases.
-- transaction-and-exact-native-preimage
BEGIN ISOLATION LEVEL SERIALIZABLE;
SET LOCAL search_path = pg_catalog;
SET LOCAL statement_timeout = '8s';
SET LOCAL lock_timeout = '2s';
SET LOCAL timezone = 'UTC';
SET LOCAL datestyle = 'ISO, YMD';
SET LOCAL standard_conforming_strings = on;
DO $owned$
BEGIN
 IF current_database() <> 'club_arena_qualification' OR inet_server_addr() IS NOT NULL
 OR current_user <> 'supabase_admin' OR session_user <> 'supabase_admin'
 OR NOT EXISTS (SELECT FROM pg_roles WHERE oid=10 AND rolname=current_user AND rolsuper)
 OR current_setting('data_directory') <> '/var/lib/postgresql/data'
 OR current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
 THEN RAISE EXCEPTION 'FIXTURE_ORIGINAL_BOOTSTRAP_REQUIRED'; END IF;
 PERFORM pg_stat_clear_snapshot();
 IF NOT EXISTS (SELECT FROM pg_stat_activity WHERE backend_type='client backend'
   AND pid=@OWNED_IDLE_APPLICATION_PID@ AND pid<>pg_backend_pid()
   AND (extract(epoch FROM backend_start)*1000000)::bigint=@OWNED_APP_START_MICROS@
   AND datname=current_database() AND usename='postgres'
   AND state='idle' AND xact_start IS NULL)
 OR EXISTS (SELECT FROM pg_stat_activity WHERE backend_type='client backend'
   AND pid<>pg_backend_pid() AND
   (pid=@OWNED_IDLE_APPLICATION_PID@
    AND (extract(epoch FROM backend_start)*1000000)::bigint=@OWNED_APP_START_MICROS@
    AND datname=current_database() AND usename='postgres'
    AND state='idle' AND xact_start IS NULL) IS NOT TRUE)
 OR EXISTS (SELECT FROM pg_prepared_xacts)
 OR EXISTS (SELECT FROM cron.job)
 THEN RAISE EXCEPTION 'FIXTURE_QUIESCENT_INSTALLATION_REQUIRED'; END IF;
END $owned$;
DO $catalog_guard$
DECLARE actual jsonb;
BEGIN
WITH known_config(key) AS (
  VALUES ('search_path'), ('statement_timeout'), ('lock_timeout'),
    ('idle_in_transaction_session_timeout'), ('default_transaction_read_only'),
    ('log_statement'), ('pgrst.db_pre_request'), ('session_preload_libraries'),
    ('app.settings.jwt_exp')
), role_rows AS (
  SELECT jsonb_build_object(
    'name', r.rolname, 'superuser', r.rolsuper, 'inherit', r.rolinherit,
    'create_role', r.rolcreaterole, 'create_db', r.rolcreatedb,
    'login', r.rolcanlogin, 'replication', r.rolreplication,
    'bypass_rls', r.rolbypassrls, 'connection_limit', r.rolconnlimit,
    'valid_until', r.rolvaliduntil::text,
    'configuration', (SELECT jsonb_agg(jsonb_build_object(
      'key', split_part(c, '=', 1),
      'value', CASE WHEN split_part(c, '=', 1) IN (SELECT key FROM known_config)
        THEN substr(c, strpos(c, '=') + 1) END,
      'value_md5', md5(substr(c, strpos(c, '=') + 1))) ORDER BY split_part(c, '=', 1))
      FROM unnest(r.rolconfig) c)) AS value
  FROM pg_roles r
), setting_rows AS (
  SELECT jsonb_build_object(
    'role', CASE WHEN s.setrole = 0 THEN 'ALL' ELSE pg_get_userbyid(s.setrole) END,
    'database', CASE WHEN s.setdatabase = 0 THEN 'ALL'
      WHEN s.setdatabase = (SELECT oid FROM pg_database WHERE datname = current_database())
        THEN 'OWNED_DATABASE'
      ELSE (SELECT datname FROM pg_database WHERE oid = s.setdatabase) END,
    'settings', (SELECT jsonb_agg(jsonb_build_object(
      'key', split_part(c, '=', 1),
      'value', CASE WHEN split_part(c, '=', 1) IN (SELECT key FROM known_config)
        THEN substr(c, strpos(c, '=') + 1) END,
      'value_md5', md5(substr(c, strpos(c, '=') + 1))) ORDER BY split_part(c, '=', 1))
      FROM unnest(s.setconfig) c)) AS value
  FROM pg_db_role_setting s
), default_rows AS (
  SELECT jsonb_build_object('creator', pg_get_userbyid(d.defaclrole),
    'schema', CASE WHEN d.defaclnamespace = 0 THEN 'GLOBAL'
      ELSE (SELECT nspname FROM pg_namespace WHERE oid = d.defaclnamespace) END,
    'type', d.defaclobjtype,
    'acl', (SELECT jsonb_agg(jsonb_build_object(
      'grantor', pg_get_userbyid(a.grantor),
      'grantee', CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
      'privilege', a.privilege_type, 'grantable', a.is_grantable)
      ORDER BY pg_get_userbyid(a.grantor),
        CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,
        a.privilege_type, a.is_grantable)
      FROM aclexplode(d.defaclacl) a)) AS value
  FROM pg_default_acl d
)
SELECT jsonb_build_object(
  'version', 1, 'scope', 'owned-post-service-preimage',
  'observed_at', clock_timestamp(), 'database', current_database(),
  'role_scope', 'all roles including unconnected builtin and fixture roles',
  'roles', (SELECT jsonb_agg(value ORDER BY value->>'name') FROM role_rows),
  'memberships', (SELECT jsonb_agg(jsonb_build_object(
    'role', pg_get_userbyid(m.roleid), 'member', pg_get_userbyid(m.member),
    'grantor', pg_get_userbyid(m.grantor), 'admin', m.admin_option,
    'inherit', m.inherit_option, 'set', m.set_option)
    ORDER BY pg_get_userbyid(m.roleid), pg_get_userbyid(m.member), pg_get_userbyid(m.grantor))
    FROM pg_auth_members m),
  'role_settings', (SELECT jsonb_agg(value ORDER BY value->>'database', value->>'role') FROM setting_rows),
  'default_acl', (SELECT jsonb_agg(value ORDER BY value->>'creator', value->>'schema', value->>'type') FROM default_rows),
  'schemas', (SELECT jsonb_agg(jsonb_build_object('name', nspname,
    'owner', pg_get_userbyid(nspowner),
    'acl', (SELECT jsonb_agg(a::text ORDER BY a::text) FROM unnest(nspacl) a)) ORDER BY nspname)
    FROM pg_namespace WHERE nspname !~ '^pg_(temp|toast)' AND nspname <> 'pg_catalog'
      AND nspname <> 'information_schema'),
  'extensions', (SELECT jsonb_agg(jsonb_build_object('name', e.extname,
    'version', e.extversion, 'schema', n.nspname, 'owner', pg_get_userbyid(e.extowner)) ORDER BY e.extname)
    FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace),
  'production_parity', false,
  'contains_passwords_or_user_rows', false
) INTO actual;
IF (actual - 'observed_at') IS DISTINCT FROM $expected${"roles":[{"name":"anon","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"authenticated","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"authenticator","login":true,"inherit":false,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":[{"key":"session_preload_libraries","value":"safeupdate","value_md5":"6dee2b8cb9ea4ffb1e97aaf1b602bc96"}],"connection_limit":-1},{"name":"dashboard_user","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_checkpoint","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_create_subscription","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_database_owner","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_execute_server_program","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_maintain","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_monitor","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_read_all_data","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_read_all_settings","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_read_all_stats","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_read_server_files","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_signal_backend","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_stat_scan_tables","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_use_reserved_connections","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_write_all_data","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"pg_write_server_files","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"postgres","login":true,"inherit":true,"create_db":true,"superuser":false,"bypass_rls":true,"create_role":true,"replication":true,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"service_role","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":true,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"supabase_admin","login":true,"inherit":true,"create_db":true,"superuser":true,"bypass_rls":true,"create_role":true,"replication":true,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"supabase_auth_admin","login":true,"inherit":false,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":true,"replication":false,"valid_until":null,"configuration":[{"key":"search_path","value":"auth","value_md5":"fa53b91ccc1b78668d5af58e1ed3a485"}],"connection_limit":-1},{"name":"supabase_privileged_role","login":false,"inherit":true,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":null,"connection_limit":-1},{"name":"supabase_realtime_admin","login":false,"inherit":false,"create_db":false,"superuser":false,"bypass_rls":false,"create_role":false,"replication":false,"valid_until":null,"configuration":[{"key":"search_path","value":"public, extensions, realtime","value_md5":"844e62be926f3e3ba657f43e17f0207b"}],"connection_limit":-1}],"scope":"owned-post-service-preimage","schemas":[{"acl":null,"name":"_realtime","owner":"supabase_admin"},{"acl":["anon=U/supabase_admin","authenticated=U/supabase_admin","dashboard_user=UC/supabase_admin","postgres=U/supabase_admin","service_role=U/supabase_admin","supabase_admin=UC/supabase