"supabase_admin","grantable":false,"privilege":"MAINTAIN"},{"grantee":"dashboard_user","grantor":"supabase_admin","grantable":false,"privilege":"REFERENCES"},{"grantee":"dashboard_user","grantor":"supabase_admin","grantable":false,"privilege":"SELECT"},{"grantee":"dashboard_user","grantor":"supabase_admin","grantable":false,"privilege":"TRIGGER"},{"grantee":"dashboard_user","grantor":"supabase_admin","grantable":false,"privilege":"TRUNCATE"},{"grantee":"dashboard_user","grantor":"supabase_admin","grantable":false,"privilege":"UPDATE"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"DELETE"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"INSERT"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"MAINTAIN"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"REFERENCES"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"SELECT"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"TRIGGER"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"TRUNCATE"},{"grantee":"postgres","grantor":"supabase_admin","grantable":false,"privilege":"UPDATE"}],"type":"r","schema":"realtime","creator":"supabase_admin"},{"acl":[{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"SELECT"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"UPDATE"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"USAGE"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"SELECT"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"UPDATE"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"USAGE"}],"type":"S","schema":"auth","creator":"supabase_auth_admin"},{"acl":[{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"EXECUTE"}],"type":"f","schema":"auth","creator":"supabase_auth_admin"},{"acl":[{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"DELETE"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"INSERT"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"MAINTAIN"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"REFERENCES"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"SELECT"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"TRIGGER"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"TRUNCATE"},{"grantee":"dashboard_user","grantor":"supabase_auth_admin","grantable":false,"privilege":"UPDATE"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"DELETE"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"INSERT"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"MAINTAIN"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"REFERENCES"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"SELECT"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"TRIGGER"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"TRUNCATE"},{"grantee":"postgres","grantor":"supabase_auth_admin","grantable":false,"privilege":"UPDATE"}],"type":"r","schema":"auth","creator":"supabase_auth_admin"}],"memberships":[{"set":true,"role":"anon","admin":false,"member":"authenticator","grantor":"supabase_admin","inherit":false},